function handleRequest(request)
    local httpStatus = 503 -- Service Unavailable by default
    local responseBody = "Service is currently unavailable."

    if request.headers["X-Custom-Trigger"] then
        return { status = httpStatus, body = responseBody }
    end

    return { status = 200, body = "Request processed successfully." }
end

function handleCORS(request)
    local origin = request.headers["Origin"] or "*"
    if request.method == "OPTIONS" then
        return {
            status = 200,
            headers = {
                ["Access-Control-Allow-Origin"] = origin,
                ["Access-Control-Allow-Methods"] = "GET, POST, PUT, DELETE",
                ["Access-Control-Allow-Headers"] = "Content-Type, Authorization"
            }
        }
    else
        -- Пропустить обычный запрос дальше
        return nil
    end
end
